        'stop'           => 'nullable|boolean',
        'closed_reason'  => 'nullable|string|max:32',
        'monthly_fee'    => 'nullable|integer|min:1',
        'settlement_day' => 'nullable|integer|min:1|max:31',
    ]);

    if (array_key_exists('name', $data) && $data['name'] !== null) {
        $pkg->name = $data['name'];
    }
    if (array_key_exists('paid', $data) && $data['paid'] !== null) {
        $pkg->paid = $data['paid'];
    }
    if (array_key_exists('paid_at', $data) && $data['paid_at'] !== null) {
        $pkg->paid_at = $data['paid_at'];
    }
    if (array_key_exists('stop', $data) && $data['stop'] !== null) {
        $pkg->stop = $data['stop'];
    }
    if (array_key_exists('closed_reason', $data) && $data['closed_reason'] !== null) {
        $pkg->closed_reason = $data['closed_reason'];
    }
    if (array_key_exists('monthly_fee', $data) && $data['monthly_fee'] !== null) {
        $pkg->monthly_fee = (int) $data['monthly_fee'];
    }
    $settlementChanged = false;
    if (array_key_exists('settlement_day', $data) && $data['settlement_day'] !== null) {
        $pkg->settlement_day = (int) $data['settlement_day'];
        $settlementChanged = true;
    }
    $pkg->save();

    // 月結方案修改 settlement_day 或 Paid 狀態時，必須同步到成員 StudentClass 的對應欄位，
    // 否則 alerts/tuition 會依舊值觸發提醒（見 R-001）。
    if ($pkg->isMonthlyBilling()) {
        $updates = [];
        if ($settlementChanged) {
            $updates['settlement_day'] = (int) $pkg->settlement_day;
        }
        if (array_key_exists('paid', $data) && $data['paid'] !== null) {
            $updates['Paid'] = $pkg->paid ? 1 : 0;
        }
        if (array_key_exists('paid_at', $data) && $data['paid_at'] !== null) {
            $updates['PayDate'] = $pkg->paid_at;
        }
        if (!empty($updates)) {
            StudentClass::where('PackageID', $pkg->id)->update($updates);
        }
    }

    return response()->json(['message' => '已更新', 'package' => $pkg]);
}

