    $query->select('StudentClass.*', 'sc_counts.cnt as monthly_session_count');

    $allRows = (clone $query)->get();

    // 月結多科方案：同一方案的各科目 StudentClass 已無 Charge（方案層收費），報表不應
    // 為每科各算一次「monthly_session × rate」（Rate 通常也為 0 或非實際費率）。
    // 做法：將方案成員從逐科行中抽出，改以「方案聚合行」呈現一次，金額 = monthly_fee。
    $monthlyPackageMembers = $allRows->filter(fn ($c) => (int) ($c->PackageID ?? 0) > 0);
    $packageIds = $monthlyPackageMembers->pluck('PackageID')->unique()->filter()->map(fn ($id) => (int) $id)->values();
    $monthlyPackages = $packageIds->isNotEmpty()
        ? CoursePackage::whereIn('id', $packageIds)
            ->where('billing_mode', CoursePackage::BILLING_MODE_MONTHLY)
            ->get()
            ->keyBy('id')
        : collect();

    // 保留非月結方案成員的逐科行（含堂數制方案成員：仍以各科 monthly_session × rate 呈現）
    $individualRows = $allRows->reject(function ($c) use ($monthlyPackages) {
        $pid = (int) ($c->PackageID ?? 0);
        return $pid > 0 && $monthlyPackages->has($pid);
    })->values();

    // 彙整每個月結方案本月所有成員的出席堂數與資訊
    $packageAggregates = [];
    foreach ($monthlyPackageMembers as $c) {
        $pid = (int) ($c->PackageID ?? 0);
        if (!$monthlyPackages->has($pid)) {
            continue;
        }
        if (!isset($packageAggregates[$pid])) {
            $packageAggregates[$pid] = [
                'sessions'      => 0,
                'student_id'    => (int) $c->StudentID,
                'student_name'  => $c->student->name ?? 'Unknown',
                'teacher_names' => [],
                'subjects'      => [],
                'members'       => [],
            ];
        }
        $packageAggregates[$pid]['sessions'] += (int) $c->monthly_session_count;
        if (!empty($c->teacher->Name)) {
            $packageAggregates[$pid]['teacher_names'][$c->teacher->Name] = true;
        }
        $packageAggregates[$pid]['subjects'][] = $c->displaySubjectName();
        $packageAggregates[$pid]['members'][] = [
            'student_class_id' => (int) $c->ID,
            'subject'          => $c->displaySubjectName(),
            'teacher_name'     => $c->teacher->Name ?? 'Unknown',
            'monthly_sessions' => (int) $c->monthly_session_count,
        ];
    }

    // 建構月結方案的虛擬報表行
    $packageRows = collect();
    foreach ($monthlyPackages as $pid => $pkg) {
        $agg = $packageAggregates[$pid] ?? [
            'sessions' => 0, 'student_id' => (int) $pkg->student_id,
            'student_name' => $pkg->student?->name ?? 'Unknown',
            'teacher_names' => [], 'subjects' => [], 'members' => [],
        ];
        $monthlyFee = (int) ($pkg->monthly_fee ?? 0);
        $packageRows->push((object) [
            '_kind'               => 'package',
            'package_id'          => (int) $pid,
            'StudentID'           => $agg['student_id'],
            'student_name_sort'   => $agg['student_name'],
            'subject_name_sort'   => $pkg->name,
            'data'                => [
                'row_type'           => 'package',
                'package_id'         => (int) $pid,
                'student_class_id'   => null,
                'student_id'         => $agg['student_id'],
                'student_name'       => $agg['student_name'],
                'subject'            => $pkg->name,
                'teacher_name'       => implode('、', array_keys($agg['teacher_names'])) ?: '—',
                'class_type'         => $pkg->class_type ?? 'one_on_one',
                'schedule_mode'      => 'date',
                'billing_mode'       => CoursePackage::BILLING_MODE_MONTHLY,
                'rate'               => $monthlyFee,
                'monthly_sessions'   => $agg['sessions'],
                'monthly_tuition'    => $monthlyFee,
                'remaining_sessions' => max(0, (int) ($pkg->remaining_sessions ?? 0)),
                'paid'               => (bool) $pkg->paid,
                'paid_at'            => $pkg->paid_at ? substr((string) $pkg->paid_at, 0, 10) : null,
                'last_paid_at'       => $pkg->paid_at ? substr((string) $pkg->paid_at, 0, 10) : null,
                'settlement_day'     => $pkg->settlement_day !== null ? (int) $pkg->settlement_day : null,
                'monthly_fee'        => $monthlyFee,
                'members'            => $agg['members'],
            ],
        ]);
    }

    // 標準化個別行的排序 key
    $individualWrapped = $individualRows->map(function ($c) {
        $c->student_name_sort = $c->student->name ?? '';
        $c->subject_name_sort = $c->displaySubjectName();
        return $c;
    });

    $combined = $individualWrapped->concat($packageRows);

    $uniqueStudents = $combined->pluck('StudentID')->unique()->count();
    $totalSessions  = $individualWrapped->sum('monthly_session_count')
        + $packageRows->sum(fn ($r) => (int) ($r->data['monthly_sessions'] ?? 0));

    $totalTuition = $individualWrapped->sum(function ($c) {
        $rate = $this->resolveRate($c);
        return $c->monthly_session_count * $rate;
    }) + $packageRows->sum(fn ($r) => (int) ($r->data['monthly_tuition'] ?? 0));

    $perPage = min((int) $request->input('per_page', 50), 200);
    $page    = max((int) $request->input('page', 1), 1);
    $total   = $combined->count();
    $lastPage = max(1, (int) ceil($total / $perPage));

    $paged = $combined->sortBy([
        fn ($a, $b) => strcmp($a->student_name_sort ?? '', $b->student_name_sort ?? ''),
        fn ($a, $b) => strcmp($a->subject_name_sort ?? '', $b->subject_name_sort ?? ''),
    ])->slice(($page - 1) * $perPage, $perPage)->values();

    // 個別行的 last_paid_at 仍用 Invoice/Payment 鍊；方案行已自帶 last_paid_at。
    $pagedIndividualIds = $paged
        ->filter(fn ($r) => !isset($r->_kind) || $r->_kind !== 'package')
        ->pluck('ID')->map(fn ($id) => (int) $id)->all();
    $paidAtMap = AlertController::lastPaidAtByStudentClassIds($pagedIndividualIds);

    $data = $paged->map(function ($c) use ($paidAtMap) {
        if (isset($c->_kind) && $c->_kind === 'package') {
            return $c->data;
        }
        $rate = $this->resolveRate($c);
        $sessions = (int) $c->monthly_session_count;
        return [
            'row_type'           => 'course',
            'student_class_id'   => (int) $c->ID,
            'student_id'         => (int) $c->StudentID,
            'student_name'       => $c->student->name ?? 'Unknown',
            'subject'            => $c->displaySubjectName(),
            'teacher_name'       => $c->teacher->Name ?? 'Unknown',
            'class_type'         => $c->ClassType ?? 'one_on_one',
            'schedule_mode'      => $c->ScheduleMode ?? 'count',
            'billing_mode'       => CoursePackage::BILLING_MODE_COUNT,
            'rate'               => round($rate, 2),
            'monthly_sessions'   => $sessions,
            'monthly_tuition'    => round($sessions * $rate, 2),
            'remaining_sessions' => max(0, (int) ($c->RemainingSessions ?? 0)),
            'paid'               => (bool) $c->Paid,
            'paid_at'            => $c->PayDate ? substr($c->PayDate, 0, 10) : null,
            'last_paid_at'       => ($c->PayDate ? substr($c->PayDate, 0, 10) : null) ?? ($paidAtMap[(int) $c->ID] ?? null),
        ];
    })->all();

    return response()->json([
        'data'    => array_values($data),
        'summary' => [
            'total_students'  => $uniqueStudents,
            'total_sessions'  => $totalSessions,
            'total_tuition'   => round($totalTuition, 2),
        ],
        'meta' => [
            'current_page' => $page,
            'last_page'    => $lastPage,
            'per_page'     => $perPage,
            'total'        => $total,
        ],
    ]);
}

