    // 排序：先依學生姓名，再科目／方案名稱
    $exportRows = $individualRows->map(function ($c) {
        return [
            'sort_student' => $c->student->name ?? '',
            'sort_subject' => $c->displaySubjectName(),
            'row'          => [
                'student_name' => $c->student->name ?? 'Unknown',
                'subject'      => $c->displaySubjectName(),
                'teacher'      => $c->teacher->Name ?? 'Unknown',
                'class_type'   => $c->ClassType ?? '',
                'sessions'     => (int) $c->monthly_session_count,
                'rate'         => $this->resolveRate($c),
                'tuition'      => round($c->monthly_session_count * $this->resolveRate($c), 2),
                'paid_at'      => $c->PayDate ? substr($c->PayDate, 0, 10) : '',
            ],
        ];
    });

    foreach ($monthlyPackages as $pid => $pkg) {
        $agg = $packageAggregates[$pid] ?? ['sessions' => 0, 'teachers' => []];
        $exportRows->push([
            'sort_student' => $pkg->student?->name ?? 'Unknown',
            'sort_subject' => $pkg->name,
