                'subject'      => $pkg->name . '（月結方案）',
                'teacher'      => implode('、', array_keys($agg['teachers'])) ?: '—',
                'class_type'   => $pkg->class_type ?? '',
                'sessions'     => (int) $agg['sessions'],
                'rate'         => (int) ($pkg->monthly_fee ?? 0),
