                'paid_at'      => $pkg->paid_at ? substr((string) $pkg->paid_at, 0, 10) : '',
            ],
        ]);
    }

    $sorted = $exportRows->sortBy([
        fn ($a, $b) => strcmp($a['sort_student'], $b['sort_student']),
        fn ($a, $b) => strcmp($a['sort_subject'], $b['sort_subject']),
    ])->pluck('row')->values();

    $branchIds = $campusIds ?: [];
    $branchName = !empty($branchIds)
        ? (DB::table('Campus')->where('id', $branchIds[0])->value('name') ?? 'all')
        : 'all';
    $filename = "當月學收_{$branchName}_{$year}{$month}.csv";

    return response()->streamDownload(function () use ($sorted) {
        $out = fopen('php://output', 'w');
        fprintf($out, chr(0xEF) . chr(0xBB) . chr(0xBF));
        fputcsv($out, ['學生', '科目', '老師', '班型', '月堂數', '費率', '月學收', '繳費日期']);
        $classTypeLabels = [
            'one_on_one' => '一對一', 'one_on_two' => '一對二',
            'one_on_three' => '一對三', 'tutoring' => '輔導', 'trial' => '試聽',
        ];
        foreach ($sorted as $row) {
            fputcsv($out, [
                $row['student_name'],
                $row['subject'],
                $row['teacher'],
                $classTypeLabels[$row['class_type']] ?? $row['class_type'],
                $row['sessions'],
                $row['rate'],
                $row['tuition'],
                $row['paid_at'],
            ]);
        }
        fclose($out);
    }, $filename, ['Content-Type' => 'text/csv; charset=UTF-8']);
}

