/**
 * 月結多科方案的提醒：以方案 settlement_day + 方案 paid 狀態為依據，
 * 金額顯示 monthly_fee，不以各科 StudentClass.Charge 過濾。
 */
private function collectMonthlyPackageAlerts($studentIds, Carbon $today)
{
    $query = CoursePackage::query()
        ->where('billing_mode', CoursePackage::BILLING_MODE_MONTHLY)
        ->where('stop', false)
        ->where('enabled', true)
        ->whereNotNull('settlement_day')
        ->whereBetween('settlement_day', [1, 31]);

    if ($studentIds !== null) {
        $query->whereIn('student_id', $studentIds);
    }

    $packages = $query->with('student')->get();
    if ($packages->isEmpty()) {
        return collect();
    }

    return $packages->map(function (CoursePackage $pkg) use ($today) {
        $settlementDay = (int) $pkg->settlement_day;
        if ($settlementDay < 1 || $settlementDay > 31) {
            return null;
        }

        $isPaid = (bool) $pkg->paid;
        $thisDue = $this->settlementDateInMonth((int) $today->year, (int) $today->month, $settlementDay);
        $dueDate = null;
        $daysLeft = null;

        if (!$isPaid) {
            if ($today->lte($thisDue)) {
                $daysLeft = (int) $today->copy()->startOfDay()->diffInDays($thisDue->copy()->startOfDay(), false);
                if ($daysLeft > 5) {
                    return null;
                }
                $dueDate = $thisDue;
            } else {
                $daysLate = (int) $thisDue->copy()->startOfDay()->diffInDays($today->copy()->startOfDay(), false);
                $daysLeft = -$daysLate;
                $dueDate = $thisDue;
            }
        } else {
            if ($today->lte($thisDue)) {
                $daysLeft = (int) $today->copy()->startOfDay()->diffInDays($thisDue->copy()->startOfDay(), false);
                if ($daysLeft > 5) {
                    return null;
                }
                $dueDate = $thisDue;
            } else {
                $nextMonth = $today->copy()->startOfMonth()->addMonthNoOverflow();
                $nextDue = $this->settlementDateInMonth((int) $nextMonth->year, (int) $nextMonth->month, $settlementDay);
                $daysLeft = (int) $today->copy()->startOfDay()->diffInDays($nextDue->copy()->startOfDay(), false);
                if ($daysLeft > 5) {
                    return null;
                }
                $dueDate = $nextDue;
            }
        }

        $monthlyFee = (int) ($pkg->monthly_fee ?? 0);

        return [
            'id'                     => 'pkg-' . $pkg->id,
            'package_id'             => (int) $pkg->id,
            'student_class_id'       => null,
            'student_id'             => (int) $pkg->student_id,
            'student_name'           => $pkg->student->name ?? 'Unknown',
            'campus_id'              => (int) ($pkg->student->CampusID ?? $pkg->campus_id ?? 0),
            'subject'                => $pkg->name,
            'schedule_mode'          => 'date',
            'billing_mode'           => CoursePackage::BILLING_MODE_MONTHLY,
            'remaining_sessions'     => max(0, (int) ($pkg->remaining_sessions ?? 0)),
            'sessions_purchased'     => (int) ($pkg->total_sessions ?? 0),
            'paid'                   => $isPaid,
            'alert_type'             => 'monthly_due_soon',
            'days_until_settlement'  => $daysLeft,
            'settlement_day'         => $settlementDay,
            'due_date'               => $dueDate ? $dueDate->toDateString() : null,
            'paid_at'                => $pkg->paid_at ? substr((string) $pkg->paid_at, 0, 10) : null,
            'last_paid_at'           => $pkg->paid_at ? substr((string) $pkg->paid_at, 0, 10) : null,
            'charge'                 => $monthlyFee,
            'paid_amount'            => $isPaid ? $monthlyFee : 0,
            'outstanding'            => $isPaid ? 0 : $monthlyFee,
            'payment_status'         => $isPaid ? 'monthly_due_soon' : 'unpaid',
            'latest_payment_report_id' => null,
            'has_newer_course'       => false,
            'newer_course_id'        => null,
            'newer_course_remaining' => null,
            'newer_course_start_date' => null,
            'monthly_fee'            => $monthlyFee,
        ];
    })->filter()->values();
}

